import{_ as a,C as r,o,c as n,E as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Remote Agent Hosts Need Correlated Multi-Stream Contracts, Not Arrival-Order Assumptions","description":"","frontmatter":{"title":"Remote Agent Hosts Need Correlated Multi-Stream Contracts, Not Arrival-Order Assumptions","date":"2026-08-08","column":"open-source-engineering","category":"daily","summary":"Once remote agent execution splits control events, tool calls, and results across independent streams, cross-stream reordering becomes a normal condition. Reliable finality must come from execution IDs, invocation IDs, sequence evidence, acknowledgements, and drain watermarks rather than arrival order or an outer completed token.","item_id":"Q-20260808-03","source_research_object":"research/analysis/Q-20260808-03-correlated-multistream-agent-host-contract.md","source_reading_result":"research/reading/Q-20260808-03-code-mode-grpc-host-protocol.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-08-correlated-multistream-host-contract-cover-v2.jpg"},"headers":[],"relativePath":"en/engineering/2026-08-08-correlated-multistream-host-contract.md","filePath":"en/engineering/2026-08-08-correlated-multistream-host-contract.md","lastUpdated":1787407830000}'),c={name:"en/engineering/2026-08-08-correlated-multistream-host-contract.md"};function l(d,e,u,m,h,p){const t=r("ArticleCover");return o(),n("div",null,[s(t,{image:"/assets/covers/daily-2026-08-08-correlated-multistream-host-contract-cover-v2.jpg",kicker:"Open-source Engineering · Daily Research",title:"Remote Agent Hosts Need Correlated Multi-Stream Contracts, Not Arrival-Order Assumptions",summary:"Once remote agent execution splits control events, tool calls, and results across independent streams, cross-stream reordering becomes a normal condition. Reliable finality must come from execution IDs, invocation IDs, sequence evidence, acknowledgements, and drain watermarks rather than arrival order or an outer completed token.",version:"Q-20260808-03",status:"Daily Runtime V5 · 2026-08-08",languageHref:"/zh/engineering/2026-08-08-correlated-multistream-host-contract",languageLabel:"中文"}),e[0]||(e[0]=i(' # Remote Agent Hosts Need Correlated Multi-Stream Contracts, Not Arrival-Order Assumptions <p>When agent execution moves behind a remote host boundary, the tempting shortcut is to treat an RPC-level <code>completed</code> signal as safe completion. The harder engineering reality is the opposite: once control events, tool subscriptions, and tool results use independent streams, <strong>reordering is not an anomaly; it is part of the contract</strong>.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p>A remote Agent Host should treat cross-stream reordering as a first-class condition. Clients must reconstruct safe finality from stable identifiers, monotonic sequence evidence, acknowledgements, and closure watermarks, while keeping transport success, execution lifecycle completion, and business success as separate dimensions.</p><p>This article consumes only the <code>Q-20260808-03</code> Research Object. Production did not reopen signals or the Reading Result for new analysis.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The sole analytical input is <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260808-03-correlated-multistream-agent-host-contract.md" target="_blank" rel="noreferrer">Research Object — Correlated Multi-Stream Agent Host Contract</a>. The Reading Result remains only the evidence-provenance path declared by that object.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object describes a versioned remote-host boundary that separates session ownership, execution, waits, cancellation, termination, tool callbacks, notifications, and typed content results. Different traffic classes may use independent HTTP/2 streams so that high-volume tool payloads do not block every control event.</p><p>The tradeoff is loss of one global arrival order. A close event arriving first does not prove that every lower-numbered tool callback has already arrived. An execution lifecycle reaching a terminal state does not prove that its nested result lacks <code>error_text</code>. A transport-successful RPC does not prove business acceptance.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Signal</th><th>What it establishes</th><th>What it does not establish</th><th>Additional evidence needed</th></tr></thead><tbody><tr><td>RPC transport success</td><td>This transport exchange succeeded</td><td>Business work is correct</td><td>Typed execution result</td></tr><tr><td><code>ExecutionCompleted</code></td><td>Execution lifecycle reached terminal state</td><td>Semantic success</td><td>Nested error/result state</td></tr><tr><td>Close / CellClosed</td><td>A close event was observed</td><td>All callbacks are drained</td><td>Sequence watermark</td></tr><tr><td>Local cancel action</td><td>Local code requested cancellation</td><td>Remote wait is retired</td><td>Remote acknowledgement</td></tr><tr><td>FCoP task state</td><td>Shared work/behavior semantics</td><td>gRPC stream order or connection liveness</td><td>Runtime transport evidence</td></tr></tbody></table><p>The table is a Research Center synthesis from the Research Object. The FCoP row is an explicit boundary statement, not a claim that FCoP is a transport protocol.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>Stream separation buys concurrency by moving correctness into correlation. An execution ID ties together one execution, an invocation ID ties together a tool call, sequence numbers reveal missing earlier events, and a final watermark defines how far a client must drain before it can safely retire local state.</p><p>Cancellation needs the same discipline. Dropping a future or closing a UI action means only that the local side stopped waiting. It does not establish that the remote host retired the old wait. An acknowledgement-bearing transition prevents late results from an earlier wait from contaminating a later execution.</p><p>The Research Object also preserves an important limitation: a package-level <code>v1</code> namespace is durable naming, not runtime feature negotiation. Authentication, authorization, retry/idempotency rules, and mixed-version capability discovery remain separate requirements for production-grade remote execution.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>If CodeFlowMu externalizes worker execution over RPC, high-volume tool payload traffic should be separable from control/event traffic while execution, invocation, wait, and cancellation receive stable IDs, sequence evidence, closure watermarks, and durable effect receipts.</p><p>WorkOrder identity should sit above a provider or host session lease. Losing a transport session may terminate a remote execution context, but it must not erase long-lived task truth. Recovery should continue from durable WorkOrder state, accepted evidence, and unresolved decisions.</p><p>FCoP should remain the shared behavioral/work protocol surface rather than absorbing gRPC ordering, connection liveness, or transport retry semantics.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The evidence is mainly a protocol/bindings change and does not demonstrate real-load concurrency performance or backpressure behavior. Stream-loss-as-session-lease semantics do not provide transparent reconnect by themselves. Authentication, feature negotiation, idempotency for mutating RPCs, and end-to-end concurrency guarantees remain unestablished.</p><p>The claim is therefore about <strong>making remote execution semantics reason-able and auditable</strong>, not proof that the protocol is already production-complete.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>Next work should identify which CodeFlowMu events need monotonic sequence numbers or closure watermarks, define a reconnect model that preserves WorkOrder continuity, add idempotency keys and durable receipts for mutating RPCs, and layer feature negotiation without coupling FCoP work semantics to transport details.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The diagram shows three independent streams converging on a correlation layer, then using sequence evidence, acknowledgement, and a drain watermark to produce safe finality. It is a Research Center synthesis and does not imply an unmeasured performance gain.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260808-03-correlated-multistream-agent-host-contract.md" target="_blank" rel="noreferrer">Research Object — Correlated Multi-Stream Agent Host Contract</a>: sole analytical input for Production.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260808-03-code-mode-grpc-host-protocol.md" target="_blank" rel="noreferrer">Reading Result — Code-mode gRPC Host Protocol</a>: evidence-provenance path declared by the Research Object; Production did not perform new research from it.</li></ol>',30))])}const v=a(c,[["render",l]]);export{b as __pageData,v as default};
